ALTER TABLE "roles" DROP CONSTRAINT "roles_code_valid";--> statement-breakpoint
ALTER TABLE "payment_attempts" DROP CONSTRAINT "payment_attempts_context_valid";--> statement-breakpoint
ALTER TABLE "payment_transactions" DROP CONSTRAINT "payment_transactions_fields_valid";--> statement-breakpoint
ALTER TABLE "refunds" DROP CONSTRAINT "refunds_fields_valid";--> statement-breakpoint
ALTER TABLE "store_settings" ADD COLUMN "manual_payment_instructions" text;--> statement-breakpoint
ALTER TABLE "store_settings" ADD COLUMN "manual_payment_hold_hours" integer DEFAULT 48 NOT NULL;--> statement-breakpoint
ALTER TABLE "store_settings" ADD CONSTRAINT "store_settings_manual_payment_valid" CHECK ("store_settings"."manual_payment_hold_hours" BETWEEN 1 AND 168 AND ("store_settings"."manual_payment_instructions" IS NULL OR length("store_settings"."manual_payment_instructions") BETWEEN 1 AND 2000));--> statement-breakpoint
ALTER TABLE "roles" ADD CONSTRAINT "roles_code_valid" CHECK ("roles"."code" IN ('super_admin','owner','editor','product_manager','support'));--> statement-breakpoint
ALTER TABLE "payment_attempts" ADD CONSTRAINT "payment_attempts_context_valid" CHECK ((("payment_attempts"."provider"='demo' AND "payment_attempts"."environment"='demo') OR ("payment_attempts"."provider" IN ('kaspi','secondary') AND "payment_attempts"."environment" IN ('sandbox','live')) OR ("payment_attempts"."provider"='manual' AND "payment_attempts"."environment"='live' AND "payment_attempts"."merchant_account"='manual')) AND length(btrim("payment_attempts"."merchant_account"))>0 AND length(btrim("payment_attempts"."merchant_reference"))>0 AND ("payment_attempts"."provider_session_id" IS NULL OR length(btrim("payment_attempts"."provider_session_id"))>0));--> statement-breakpoint
ALTER TABLE "payment_transactions" ADD CONSTRAINT "payment_transactions_fields_valid" CHECK ("payment_transactions"."currency"='KZT' AND "payment_transactions"."amount_minor">0 AND (("payment_transactions"."provider" IN ('kaspi','secondary') AND "payment_transactions"."environment" IN ('sandbox','live')) OR ("payment_transactions"."provider"='manual' AND "payment_transactions"."environment"='live' AND "payment_transactions"."merchant_account"='manual')) AND "payment_transactions"."kind" IN ('authorization','capture','void') AND length(btrim("payment_transactions"."external_id"))>0 AND length(btrim("payment_transactions"."merchant_account"))>0 AND length(btrim("payment_transactions"."dedupe_key"))>0 AND jsonb_typeof("payment_transactions"."evidence")='object' AND "payment_transactions"."refund_epoch">=0);--> statement-breakpoint
ALTER TABLE "refunds" ADD CONSTRAINT "refunds_fields_valid" CHECK ("refunds"."currency"='KZT' AND "refunds"."amount_minor">0 AND "refunds"."version">0 AND (("refunds"."provider" IN ('kaspi','secondary') AND "refunds"."environment" IN ('sandbox','live')) OR ("refunds"."provider"='manual' AND "refunds"."environment"='live' AND "refunds"."merchant_account"='manual')) AND length(btrim("refunds"."merchant_account"))>0 AND ("refunds"."provider_refund_id" IS NULL OR length(btrim("refunds"."provider_refund_id"))>0) AND "refunds"."idempotency_key" ~ '^[ -~]{16,128}$' AND "refunds"."request_hash" ~ '^[0-9a-f]{64}$' AND "refunds"."status" IN ('reserved','pending','unknown','succeeded','failed','cancelled'));--> statement-breakpoint
-- O07 (Task 21C): manual payment confirmation needs payments:confirm, granted to super_admin and the
-- new owner role. Bootstrap seeds roles only once, so an already bootstrapped database gets them here.
-- The owner role also receives every other permission that already exists (bootstrap's owner default).
INSERT INTO "permissions"("id","code") VALUES (gen_random_uuid(),'payments:confirm') ON CONFLICT ("code") DO NOTHING;--> statement-breakpoint
INSERT INTO "roles"("id","code") VALUES (gen_random_uuid(),'super_admin'),(gen_random_uuid(),'owner') ON CONFLICT ("code") DO NOTHING;--> statement-breakpoint
INSERT INTO "role_permissions"("role_id","permission_id") SELECT r."id",p."id" FROM "roles" r JOIN "permissions" p ON p."code"='payments:confirm' WHERE r."code" IN ('super_admin','owner') ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO "role_permissions"("role_id","permission_id") SELECT r."id",p."id" FROM "roles" r CROSS JOIN "permissions" p WHERE r."code"='owner' ON CONFLICT DO NOTHING;
